#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using PVZEngine.Tools.Timing;

namespace MVZ2.GameContent.Enemies
{
    /// <summary>
    /// 橄榄球僵尸的动画行为：冲撞和近战阶段使用各自的专属动画。
    /// 近战每轮只播一次 attack（进入攻击状态瞬间从 0 帧起播），播完回到站立等下一轮。
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.footballZombie_Animation)]
    public class FootballZombie_AnimationBehaviour : EnemyCommonAnimationBehaviour
    {
        public FootballZombie_AnimationBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        public override void UpdateAnimationParameters(Entity entity, int state)
        {
            base.UpdateAnimationParameters(entity, state);
            if (state != STATE_MELEE_ATTACK)
                return;
            // 每轮周期的前 25 tick 播 attack（一个循环，不重进状态），
            // 其余时间回站立。用状态计时器判断当前处于哪一段。
            var timer = entity.GetBehaviourField<FrameTimer>(FootballZombie.FIELD_ATTACK_TIMER);
            var attacking = timer != null && timer.Frame >= ATTACK_ANIMATION_TICKS;
            entity.SetAnimationInt("AnimationState", attacking ? ANIMATION_STATE_FOOTBALL_ATTACK : ANIMATION_STATE_IDLE);
        }
        public override int GetAnimationState(int state)
        {
            if (state == FootballZombie.STATE_IMPACT)
                return ANIMATION_STATE_IMPACT;
            return base.GetAnimationState(state);
        }
        public const int ANIMATION_STATE_IMPACT = ANIMATION_STATE_PRIVATE + 0;
        public const int ANIMATION_STATE_FOOTBALL_ATTACK = ANIMATION_STATE_PRIVATE + 1;
        public const int ATTACK_ANIMATION_TICKS = 25;
    }
}
